func TestWordCount(t *testing.T) {
	tests := []struct {
		name string
		in   string
		want map[string]int
	}{
		{"empty", "", map[string]int{}},
		{"single", "a", map[string]int{"a": 1}},
		{"two", "a b", map[string]int{"a": 1, "b": 1}},
		{"with spaces", "a b c a", map[string]int{"a": 2, "b": 1, "c": 1}},
		{"with punctuation", "a,b c:a", map[string]int{"a,b": 1, "c:a": 1}},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := WordCount(tt.in)
			if !maps.Equal(got, tt.want) {
				t.Errorf("WordCount(%q) = %v, want %v", tt.in, got, tt.want)
			}
		})
	}
}

// maps.Equal reports whether the two maps are equal (same keys, same values).
func mapsEqual(m1, m2 map[string]int) bool {
	if len(m1) != len(m2) {
		return false
	}
	for k, v := range m1 {
		if m2[k] != v {
			return false
		}
	}
	return true
}

