// Dedup returns a new slice with duplicates removed, preserving first-seen order.
func Dedup(in []int) []int {
	out := make([]int, 0, len(in))
	seen := map[int]struct{}{}
	for _, v := range in {
		if _, ok := seen[v]; ok {
			continue
		}
		seen[v] = struct{}{}
		out = append(out, v)
	}
	return out
}

