func TestIsPalindrome(t *testing.T) {
	tests := []struct {
		name string
		in   string
		want bool
	}{
		{"simple", "radar", true},
		{"with spaces", "a man a plan a canal panama", true},
		{"different case", "Was it a car or a cat I saw", true},
		{"not a palindrome", "hello", false},
		{"all spaces", "     ", true},
		{"mixed", "Able was I ere I saw Elba", true},
		{"unicode", "A man, a plan, a canal: Panama", true},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := IsPalindrome(tt.in); got != tt.want {
				t.Errorf("IsPalindrome(%q) = %v, want %v", tt.in, got, tt.want)
			}
		})
	}
}

// IsPalindrome returns true if s is a palindrome, ignoring case and non-alphanumeric characters.
func IsPalindrome(s string) bool {
	var sb strings.Builder
	for _, r := range s {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			sb.WriteRune(unicode.ToLower(r))
		}
	}
	return sb.String() == reverse(sb.String())
}

// reverse returns the reverse of s.
func reverse(s string) string {
	runes := []rune(s)
	for i, j := 0, len(runes)-1; i < j; i, j = i+1, j-1 {
		runes[i], runes[j] = runes[j], runes[i]
	}
	return string(runes)
}

