func TestCounterConcurrentInc(t *testing.T) {
	var c Counter
	var wg sync.WaitGroup
	for i := 0; i < 50; i++ {
		wg.Add(2)
		go func() {
			defer wg.Done()
			c.Inc("k")
		}()
		go func() {
			defer wg.Done()
			_ = c.Get("k")
		}()
	}
	wg.Wait()
	if got := c.Get("k"); got != 50 {
		t.Errorf("Get(k) = %d, want 50", got)
	}
}

