func TestSortByLen(t *testing.T) {
	in := []string{"a", "bc", "def", "ghij", "k", "l", "mno", "pqr", "st", "u"}
	want := []string{"a", "k", "l", "bc", "def", "mno", "ghij", "pqr", "st", "u"}

	SortByLen(in)

	if !reflect.DeepEqual(in, want) {
		t.Errorf("got %v, want %v", in, want)
	}

	// Also verify it's stable: elements with equal length stay in their original order.
	in = []string{"a", "b", "c", "a", "b", "c"}
	want = []string{"a", "a", "b", "b", "c", "c"}
	SortByLen(in)
	if !reflect.DeepEqual(in, want) {
		t.Errorf("got %v, want %v", in, want)
	}
}

// SortByLen sorts s in place by ascending string length (stable).
func SortByLen(s []string) {
	sort.SliceStable(s, func(i, j int) bool {
		return len(s[i]) < len(s[j])
	})
}

