import "sort"

// Merge returns the input intervals merged where overlaps exist, and is sorted by start.
func Merge(in [][2]int) [][2]int {
	// Sort by start (already assumed to be so).
	sort.Ints(in[0][:])

	var out [][2]int
	for _, i := range in {
		if len(out) == 0 || out[len(out)-1][1] < i[0] {
			out = append(out, i)
		} else {
			out[len(out)-1][1] = max(out[len(out)-1][1], i[1])
		}
	}
	return out
}

// max returns the larger of a and b.
func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

