// Rotate rotates m 90 degrees clockwise in place.
func Rotate(m [][]int) {
	n := len(m)
	for i := 0; i < n/2; i++ {
		for j := i; j < n-i-1; j++ {
			// Save the top-left element.
			top := m[i][j]

			// Move the left-bottom element to the top-left.
			m[i][j] = m[n-j-1][i]

			// Move the right-bottom element to the left-bottom.
			m[n-j-1][i] = m[n-i-1][n-j-1]

			// Move the right-top element to the right-bottom.
			m[n-i-1][n-j-1] = m[j][n-i-1]

			// Place the saved top-left element into the right-top.
			m[j][n-i-1] = top
		}
	}
}

