// maps.Equal compares the two maps key-for-key.
func mapsEqual(a, b map[string][]string) bool {
	if len(a) != len(b) {
		return false
	}
	for k, avals := range a {
		bvals, ok := b[k]
		if !ok {
			return false
		}
		if len(avals) != len(bvals) {
			return false
		}
		for i, av := range avals {
			if av != bvals[i] {
				return false
			}
		}
	}
	return true
}

