// UpperReader is a reader that returns the same bytes upper-cased (ASCII).
type UpperReader struct {
	r io.Reader
}

// NewUpperReader returns a new UpperReader wrapping r.
func NewUpperReader(r io.Reader) *UpperReader {
	return &UpperReader{r: r}
}

// Read reads from the underlying reader and returns the upper-cased bytes.
func (u *UpperReader) Read(p []byte) (int, error) {
	n, err := u.r.Read(p)
	for i := 0; i < n; i++ {
		p[i] = p[i] & 0x5F
	}
	return n, err
}

